def build_entry(title, abstract, objectives, batch="2023-2024"):
    return {"title": title, "abstract": abstract, "objectives": objectives, "batch": batch}

corpus = []
positive_pairs = []  # (doc_id_a, doc_id_b) known-similar
doc_id = 1

for pair in DUPLICATE_PAIRS:
    a = build_entry(pair["a"]["title"], pair["a"]["abstract"], pair["a"]["objectives"])
    b = build_entry(pair["b"]["title"], pair["b"]["abstract"], pair["b"]["objectives"])
    a["id"] = doc_id; corpus.append(a); id_a = doc_id; doc_id += 1
    b["id"] = doc_id; corpus.append(b); id_b = doc_id; doc_id += 1
    positive_pairs.append((id_a, id_b, pair["topic"]))

for title, abstract, objectives in UNIQUE_TOPICS:
    e = build_entry(title, abstract, objectives)
    e["id"] = doc_id
    corpus.append(e)
    doc_id += 1

print(f"Total corpus size: {len(corpus)}")
print(f"Known positive (similar) pairs: {len(positive_pairs)}")

with open(os.path.join(OUT_DIR, "corpus.json"), "w", encoding="utf-8") as f:
    json.dump({"corpus": corpus, "positive_pairs": positive_pairs}, f, ensure_ascii=False, indent=2)
print("saved corpus.json")
